// EdgeModels is the resolver for the EdgeModels field.
func (r *queryResolver) EdgeModels(ctx context.Context) ([]*model.ModelInfo, error) {
	token := GatewayTokenFromContext(ctx)
	if token == nil {
		return nil, fmt.Errorf("unauthorized")
	}

	txn := types.SECRET_DB.NewTransaction()
	defer txn.Rollback()

	// 使用当前用户地址作为 caller 创建 runtime，以便 GetProviderByOwner 能正确识别
	runtime := runtime.NewRuntimeWithVersion(0, time.Now(), txn, token.Addr, chaintypes.UniAddr{}, module.NativeVersion)

	ins := gateway.NewGateway(runtime)
	query := gateway.GatewayQuery{Gateway: *ins}

	// 查询当前用户的 provider ID
	opt, err := query.GetProviderByOwner()
	if err != nil {
		return nil, err
	}
	if opt.IsNone() {
		return []*model.ModelInfo{}, nil
	}
	providerID, err := opt.UnWrap()
	if err != nil {
		return nil, err
	}

	// 获取该 provider 下的所有模型
	models, err := query.ListProviderModels(providerID)
	if err != nil {
		return nil, err
	}

	// 过滤 providerType == 9999 的本地模型
	result := make([]*model.ModelInfo, 0, len(models))
	for _, mid := range models {
		m := mid.Data
		if m.ProviderType == 9999 && m.IsActive {
			result = append(result, &model.ModelInfo{
				Name:            m.Name,
				ProviderID:      int(m.ProviderID),
				ProviderType:    int(m.ProviderType),
				ModelID:         m.ModelID,
				URI:             m.URI,
				InputModalities: int(m.InputModalities),
				ContextLength:   int(m.ContextLength),
				InPrice:         int(m.InPrice),
				CachedPrice:     int(m.CachedPrice),
				OutPrice:        int(m.OutPrice),
				IsActive:        m.IsActive,
				CreatedAt:       int(m.CreatedAt),
			})
		}
	}

	return result, nil
}

// Models is the resolver for the Models field.
// 返回模型与路由的混合列表；route 与独立模型同名时，route 优先覆盖。
// 模型端应用全部筛选条件（context、价格、模态）；路由端仅按名称关键字与价格过滤，
// context / 模态对路由无意义故不施加。
func (r *queryResolver) Models(ctx context.Context, keyword *string, minContext *int, maxContext *int, minPrice *int, maxPrice *int, modalities *int, offset *int, limit *int) ([]*model.ModelInfoWithProvider, error) {
	var kw string
	if keyword != nil {
		kw = *keyword
	}

	// 1. 模型：走 GatewayModelIndex，应用全部筛选条件。
	modelIdxRaw, err := r.Indexer.Get(indexer.GatewayModelIndexName)
	if err != nil {
		return nil, err
	}

	modelIdx, ok := modelIdxRaw.(*indexer.GatewayModelIndex)
	if !ok {
		return nil, fmt.Errorf("invalid gateway model index type")
	}

	modelReq := indexer.GatewayModelSearchRequest{
		Keyword: kw,
		Offset:  0,
		Limit:   100000,
	}

	if minContext != nil {
		v := uint64(*minContext)
		modelReq.MinContext = &v
	}

	if maxContext != nil {
		v := uint64(*maxContext)
		modelReq.MaxContext = &v
	}

	if minPrice != nil {
		v := uint64(*minPrice)
		modelReq.MinPrice = &v
	}

	if maxPrice != nil {
		v := uint64(*maxPrice)
		modelReq.MaxPrice = &v
	}

	if modalities != nil {
		modelReq.Modalities = uint8(*modalities)
	}

	models, err := modelIdx.Search(ctx, modelReq)
	if err != nil {
		return nil, err
	}

	// 2. 路由：走 GatewayRouterIndex，仅应用名称关键字过滤。
	routerIdxRaw, err := r.Indexer.Get(indexer.GatewayRouterIndexName)
	if err != nil {
		return nil, err
	}

	routerIdx, ok := routerIdxRaw.(*indexer.GatewayRouterIndex)
	if !ok {
		return nil, fmt.Errorf("invalid gateway router index type")
	}

	routes, err := routerIdx.Search(ctx, indexer.GatewayRouterSearchRequest{
		Keyword: kw,
		Offset:  0,
		Limit:   100000,
	})
	if err != nil {
		return nil, err
	}

	pool := localtunnel.GetGlobalPool()

	// 3. models 和 routes 都直接进列表。
	result := make([]*model.ModelInfoWithProvider, 0, len(models)+len(routes))
	// 4. 收集可用的模型 ID，用于判断路由是否有后端。
	modelIDSet := make(map[uint64]struct{}, len(models))
	for _, item := range models {
		m := item.Model
		// 个人算力（ProviderType 9999）必须存在可用本地隧道连接才展示
		if m.ProviderType == 9999 && !pool.HasEntry(m.ProviderID, m.Name) {
			continue
		}

		// 跳过没有服务的模型
		if m.ProviderType < 9999 && len(m.APIKeys) == 0 {
			continue
		}

		p := item.Provider
		modelIDs := make([]int, len(p.ModelIds))
		for i, v := range p.ModelIds {
			modelIDs[i] = int(v)
		}

		result = append(result, &model.ModelInfoWithProvider{
			ID: int(item.ID),
			Model: &model.ModelInfo{
				Name:            m.Name,
				ProviderID:      int(m.ProviderID),
				ProviderType:    int(m.ProviderType),
				ModelID:         m.ModelID,
				URI:             m.URI,
				InputModalities: int(m.InputModalities),
				ContextLength:   int(m.ContextLength),
				InPrice:         int(m.InPrice),
				CachedPrice:     int(m.CachedPrice),
				OutPrice:        int(m.OutPrice),
				IsActive:        m.IsActive,
				CreatedAt:       int(m.CreatedAt),
			},
			Provider: &model.ProviderInfo{
				Owner:         p.Owner.String(),
				Name:          p.Name,
				LogoURL:       p.LogoURL,
				Description:   p.Description,
				ModelIds:      modelIDs,
				Region:        int(p.Region),
				Deposit:       int(p.Deposit),
				FeeRate:       int(p.FeeRate),
				Priority:      int(p.Priority),
				TotalRequests: int(p.TotalRequests),
				SuccessRate:   int(p.SuccessRate),
				AvgLatency:    int(p.AvgLatency),
				UptimeSLA:     int(p.UptimeSLA),
				IsActive:      p.IsActive,
				CreatedAt:     int(p.CreatedAt),
			},
		})
		modelIDSet[item.ID] = struct{}{}
	}

	for _, route := range routes {
		d := route.Data
		// 跳过空路由模板（未关联任何模型）：这些是供模型加入的容器，
		// 本身不可调用，在 models 列表里只会显示为空条目，干扰前端。
		if len(d.ModelIds) == 0 {
			continue
		}

		// 路由在索引层不支持价格范围，这里按 inPrice 在内存中补一道价格过滤。
		if minPrice != nil && d.InPrice < uint64(*minPrice) {
			continue
		}

		if maxPrice != nil && d.InPrice > uint64(*maxPrice) {
			continue
		}

		// 个人算力路由只有当其包含的模型至少有一个存在于 models 中时才算有后端。
		if d.RouteType == gateway.EdgeRoute {
			hasBackend := false
			for _, modelID := range d.ModelIds {
				if _, ok := modelIDSet[modelID]; ok {
					hasBackend = true
					break
				}
			}
			if !hasBackend {
				continue
			}
		}

		modelIds := make([]int, 0, len(d.ModelIds))
		for _, modelID := range d.ModelIds {
			if _, ok := modelIDSet[modelID]; ok {
				modelIds = append(modelIds, int(modelID))
			}
		}

		if len(modelIds) == 0 {
			continue
		}

		result = append(result, &model.ModelInfoWithProvider{
			ID: int(route.ID),
			Route: &model.RouteInfo{
				ID:          int(route.ID),
				Name:        d.Name,
				RouteType:   int(d.RouteType),
				InPrice:     int(d.InPrice),
				OutPrice:    int(d.OutPrice),
				CachedPrice: int(d.CachedPrice),
				ModelIds:    modelIds,
				IsActive:    d.IsActive,
				IsOfficial:  d.IsOfficial,
				CreatedAt:   int(d.CreatedAt),
			},
		})
	}

	return result, nil
}

// EdgeModelRunningStatus is the resolver for the edge_model_running_status field.
func (r *queryResolver) EdgeModelRunningStatus(ctx context.Context, providerID int, modelNames []string) ([]*model.ModelRunningStatus, error) {
	pool := localtunnel.GetGlobalPool()

	result := make([]*model.ModelRunningStatus, 0, len(modelNames))
	for _, name := range modelNames {
		result = append(result, &model.ModelRunningStatus{
			ModelName: name,
			IsRunning: pool.HasEntry(uint64(providerID), name),
		})
	}

	return result, nil
}
